"use client";
/* eslint-disable @next/next/no-img-element -- QR codes are generated by our authenticated login route. */
import { useCallback, useEffect, useRef, useState } from "react";
import { AppButton } from "@/components/ui/AppButton";
import { songRequest } from "@/lib/anisong/client";
import { MAX_TRACKS, KIND_LABELS, SONG_KINDS, type SongTrack } from "@/lib/anisong/types";
import type { NeteaseAccount, NeteaseSong } from "@/lib/anisong/netease/types";
import { SongCover } from "./SongCover";
const accountUrl = "/api/anisong/netease/account";
const accountAction = <T,>(action: string, signal?: AbortSignal) => songRequest<T>(accountUrl, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action }), signal });

export function SongNeteaseSearch({ tracks, disabled, onSave, initialOpen = false }: { tracks: SongTrack[]; disabled: boolean; onSave: (form: FormData) => Promise<boolean>; initialOpen?: boolean }) {
  const [open, setOpen] = useState(initialOpen);
  return <section className="rounded-2xl border border-white/10 bg-slate-950/30 p-4 sm:p-5">
    <div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="font-semibold">从网易云找歌</h2><p className="mt-1 text-xs text-slate-400">搜索歌曲和封面，加入曲单后试听、比较。</p></div><AppButton variant="secondary" disabled={disabled} onClick={() => setOpen(value => !value)}>{open ? "收起网易云搜索" : "打开网易云搜索"}</AppButton></div>
    {open && <SearchPanel tracks={tracks} disabled={disabled} onSave={onSave} />}
  </section>;
}
function SearchPanel({ tracks, disabled, onSave }: { tracks: SongTrack[]; disabled: boolean; onSave: (form: FormData) => Promise<boolean> }) {
  const [account, setAccount] = useState<NeteaseAccount | null>(null);
  const [accountError, setAccountError] = useState("");
  const [accountBusy, setAccountBusy] = useState(false);
  const [qr, setQr] = useState<{ image: string; expiresAt: number } | null>(null);
  const [qrMessage, setQrMessage] = useState("");
  const [query, setQuery] = useState("");
  const [searched, setSearched] = useState("");
  const [songs, setSongs] = useState<NeteaseSong[]>([]);
  const [searching, setSearching] = useState(false);
  const [searchError, setSearchError] = useState("");
  const [adding, setAdding] = useState<string | null>(null);
  const [added, setAdded] = useState("");
  const metadata = useRef<HTMLFormElement>(null);
  const searchRequest = useRef<AbortController | null>(null);
  const actionRequest = useRef<AbortController | null>(null);
  const importLock = useRef(false);
  const loadAccount = useCallback(async (signal?: AbortSignal) => {
    try { const data = await songRequest<NeteaseAccount>(accountUrl, { signal }); if (!signal?.aborted) { setAccount(data); setAccountError(""); } }
    catch (error) { if (!signal?.aborted) setAccountError(error instanceof Error ? error.message : "无法读取登录状态"); }
  }, []);
  useEffect(() => {
    const controller = new AbortController(); void loadAccount(controller.signal);
    return () => { controller.abort(); searchRequest.current?.abort(); actionRequest.current?.abort(); };
  }, [loadAccount]);
  useEffect(() => {
    if (!qr) return;
    const controller = new AbortController(); let timer: ReturnType<typeof setTimeout>;
    async function poll() {
      if (Date.now() >= qr!.expiresAt) { setQr(null); setQrMessage("二维码已过期，请重新生成"); return; }
      try {
        const response = await accountAction<{ state: "connected" | "expired" | "waiting" | "confirm" }>("poll", controller.signal);
        if (controller.signal.aborted) return;
        if (response.state === "connected") { setQr(null); setQrMessage("网易云已连接"); window.dispatchEvent(new Event("anisong:netease-account")); await loadAccount(controller.signal); return; }
        if (response.state === "expired") { setQr(null); setQrMessage("二维码已过期，请重新生成"); return; }
        setQrMessage(response.state === "confirm" ? "已扫码，请在网易云 App 确认登录" : "请使用网易云音乐 App 扫码");
        timer = setTimeout(poll, 3000);
      } catch (error) { if (!controller.signal.aborted) { setQr(null); setAccountError(error instanceof Error ? error.message : "无法检查扫码状态"); } }
    }
    timer = setTimeout(poll, 3000);
    return () => { controller.abort(); clearTimeout(timer); };
  }, [qr, loadAccount]);
  async function login(action: "start" | "disconnect") {
    if (accountBusy) return;
    const controller = new AbortController(); actionRequest.current = controller;
    setAccountBusy(true); setAccountError(""); setQr(null); setQrMessage("");
    try {
      if (action === "start") { const value = await accountAction<{ image: string; expiresAt: number }>(action, controller.signal); if (!controller.signal.aborted) setQr(value); }
      else { await accountAction(action, controller.signal); window.dispatchEvent(new Event("anisong:netease-account")); await loadAccount(controller.signal); }
    } catch (error) { if (!controller.signal.aborted) setAccountError(error instanceof Error ? error.message : "操作失败"); }
    finally { if (!controller.signal.aborted) setAccountBusy(false); }
  }
  async function search() {
    const value = query.trim(); if (!value) return;
    searchRequest.current?.abort(); const controller = new AbortController(); searchRequest.current = controller;
    setSearching(true); setSearchError(""); setAdded("");
    try { const response = await songRequest<{ songs: NeteaseSong[] }>(`/api/anisong/netease/search?q=${encodeURIComponent(value)}`, { signal: controller.signal }); if (!controller.signal.aborted) { setSongs(response.songs); setSearched(value); } }
    catch (error) { if (!controller.signal.aborted) setSearchError(error instanceof Error ? error.message : "搜索失败"); }
    finally { if (!controller.signal.aborted) setSearching(false); }
  }
  async function add(song: NeteaseSong) {
    if (disabled || importLock.current || !metadata.current) return;
    if (!metadata.current.reportValidity()) return;
    importLock.current = true; setAdding(song.id); setAdded("");
    const form = new FormData(metadata.current);
    form.set("neteaseId", song.id); form.set("title", song.title); form.set("artist", song.artist); form.set("clipStart", "0"); form.set("clipLength", "30");
    try { if (await onSave(form)) setAdded(`已加入「${song.title}」，可在曲单中试听或编辑`); }
    finally { importLock.current = false; setAdding(null); }
  }
  const unavailable = account?.enabled === false;
  return <div className="mt-5 space-y-4">
    <div className="rounded-xl border border-white/10 p-3 text-sm">
      <div className="flex flex-wrap items-center justify-between gap-2"><p>{unavailable ? "网易云服务尚未配置，可继续使用本地音频。" : account?.connected ? `已连接：${account.nickname}` : "可先尝试匿名搜索；需要账号权限时再扫码连接。"}</p>
        {!unavailable && <AppButton size="sm" variant="ghost" disabled={accountBusy || disabled || Boolean(qr)} onClick={() => void login(account?.connected ? "disconnect" : "start")}>{accountBusy ? "正在处理…" : account?.connected ? "断开网易云" : "扫码连接网易云"}</AppButton>}</div>
      {account?.message && <p className="mt-2 text-amber-200">{account.message}</p>}
      {qr && <div className="mt-4 flex flex-wrap items-center gap-4"><img src={qr.image} alt="网易云登录二维码" width={180} height={180} className="rounded-xl bg-white p-2" /><p className="max-w-xs text-xs leading-6 text-slate-400">使用你自己的网易云账号扫码。登录状态仅用于当前 AniMatch 用户，其他用户不会共享你的账号。</p></div>}
      {qrMessage && <p role="status" className="mt-2 text-xs text-anime-cyan">{qrMessage}</p>}
      {accountError && <p role="alert" className="mt-2 text-xs text-amber-200">{accountError}</p>}
    </div>
    <form className="flex gap-2" onSubmit={event => { event.preventDefault(); void search(); }}><input aria-label="网易云搜索关键词" value={query} onChange={event => setQuery(event.target.value)} maxLength={100} placeholder="歌名 + 歌手，如 YOASOBI アイドル" className="anime-field min-w-0 flex-1" disabled={unavailable} /><AppButton type="submit" disabled={unavailable || searching || !query.trim()}>{searching ? "搜索中…" : "搜索"}</AppButton></form>
    <form ref={metadata} onSubmit={event => event.preventDefault()} className="grid gap-3 sm:grid-cols-4">
      <label className="text-xs text-slate-400">加入时的类型<select name="kind" defaultValue="OP" className="anime-field mt-1" disabled={disabled || Boolean(adding)}>{SONG_KINDS.map(kind => <option key={kind} value={kind}>{KIND_LABELS[kind]}</option>)}</select></label>
      <label className="text-xs text-slate-400">所属动画<input name="anime" maxLength={120} placeholder="可选，加入后也能修改" className="anime-field mt-1" disabled={disabled || Boolean(adding)} /></label>
      <label className="text-xs text-slate-400">年份<input name="year" type="number" min={1900} max={2100} placeholder="可选" className="anime-field mt-1" disabled={disabled || Boolean(adding)} /></label>
      <label className="text-xs text-slate-400">季度<select name="quarter" className="anime-field mt-1" disabled={disabled || Boolean(adding)}><option value="">未指定</option>{["冬季", "春季", "夏季", "秋季"].map((label, index) => <option key={label} value={index + 1}>{label}</option>)}</select></label>
    </form>
    {searchError && <p role="alert" className="text-sm text-amber-200">{searchError}</p>}
    {added && <p role="status" className="text-sm text-anime-cyan">{added}</p>}
    {searched && <p className="text-xs text-slate-400">「{searched}」· {songs.length ? `显示 ${songs.length} 个版本，请核对歌手和专辑。` : "没有找到歌曲，试试日文歌名或歌手名。"}</p>}
    <ul className="max-h-[32rem] space-y-2 overflow-y-auto">{songs.map(song => {
      const exists = tracks.some(track => track.source.kind === "netease" && track.source.id === song.id);
      return <li key={song.id} className="flex items-start gap-3 rounded-xl border border-white/10 p-3"><SongCover src={song.coverUrl} title={song.title} className="w-16 sm:w-20" /><div className="min-w-0 flex-1"><p className="break-words text-sm font-semibold">{song.title}</p><p className="mt-1 break-words text-xs text-slate-300">{song.artist}</p><p className="mt-1 break-words text-xs text-slate-500">{song.album} · {Math.floor(song.duration / 60000)}:{String(Math.floor(song.duration / 1000) % 60).padStart(2, "0")}</p><div className="mt-2 flex flex-wrap items-center gap-3"><AppButton size="sm" variant="secondary" disabled={disabled || Boolean(adding) || exists || tracks.length >= MAX_TRACKS} onClick={() => void add(song)}>{exists ? "已在曲单" : adding === song.id ? "加入中…" : "加入曲单"}</AppButton><a href={`https://music.163.com/#/song?id=${song.id}`} target="_blank" rel="noreferrer" className="text-xs text-slate-400 underline">网易云 ↗</a>{song.restricted && <span className="text-xs text-amber-200">可能需要会员或购买</span>}</div></div></li>;
    })}</ul>
    <p className="text-xs leading-5 text-slate-500">加入后默认试听前30秒。平台可能只提供试听片段或暂无音源，可在曲单中更换版本或上传本地音频。</p>
  </div>;
}
